// This builds a semantic nav from [url, text] pairs
function makeNav(links) {
  const items = links.map(function(pair) {
    return '<a href="' + pair[0] + '">' + pair[1] + "</a>";
  }).join("");
  return "<nav>" + items + "</nav>";
}
console.log(makeNav([["/", "Home"], ["/gigs", "Gigs"]]));

