// This tells semantic tags apart from generic boxes like div
function isSemantic(tag) {
  const semantic = ["header", "nav", "main", "section", "article", "aside", "footer", "figure", "figcaption", "time", "address"];
  return semantic.indexOf(tag.toLowerCase()) !== -1;
}
console.log(isSemantic("nav"));
console.log(isSemantic("div"));

